{
  "action": "ACCOUNT_MANAGER",
  "conditions": [
    {"attr": "customer_tier", "op": "eq", "value": "enterprise"},
    {"attr": "prior_tickets_30d", "op": "gte", "value": 5}
  ],
  "beats": [],
  "loses_to": [],
  "note": "Enterprise customers with a high ticket volume (5+ in 30 days) warrant proactive account management to address recurring issues, regardless of low severity."
}

{
  "action": "T2_TECHNICAL",
  "conditions": [
    {"attr": "product", "op": "eq", "value": "dashboard"},
    {"attr": "severity", "op": "lte", "value": 3},
    {"attr": "off_hours", "op": "eq", "value": true}
  ],
  "beats": [],
  "loses_to": [],
  "note": "Dashboard issues with moderate severity during off-hours require technical support; this rule generalizes to any off-hours dashboard ticket with severity 3 or lower, as the technical team handles such configuration or usage problems."
}

{
  "action": "T2_TECHNICAL",
  "conditions": [
    {"attr": "product", "op": "eq", "value": "dashboard"},
    {"attr": "severity", "op": "lte", "value": 3},
    {"attr": "off_hours", "op": "eq", "value": true}
  ],
  "beats": [],
  "loses_to": ["R0001"],
  "note": "Dashboard issues with moderate severity during off-hours require technical support; this rule generalizes to any off-hours dashboard ticket with severity 3 or lower, as the technical team handles such configuration or usage problems. Since R0001 covers enterprise customers with many prior tickets, which is a more specific account management case, R0001 takes precedence where both apply."
}

{
  "action": "SELF_SERVICE_DEFLECT",
