  "beats": [],
  "loses_to": [],
  "note": "Ticket de baja severidad, usuario free sin historial reciente y sin indicios de seguridad: apto para autoservicio. La regla se abstrae a severidad >=3, tier free y pocos tickets previos para cubrir casos análogos."
}

{
  "action": "SELF_SERVICE_DEFLECT",
  "conditions": [
    {"attr": "severity", "op": "gte", "value": 3},
