  ],
  "beats": ["R0002"],
  "loses_to": ["R0005"],
  "note": "Mi regla cubre tickets free, off_hours y severidad >=3. R0002 cubre dashboard, severity <=3 y off_hours, pero no restringe tier; mi regla es más específica en tier (free) y más general en producto, y al solaparse en casos free+off_hours+severity 3 o 4, mi regla debe ganar porque el tier free y off_hours juntos indican autoservicio. R0005 cubre free, mobile, chat y prior_tickets_30d >=10; mi regla no restringe producto ni canal ni prior_tickets_30d, por lo que es más general en esos aspectos; donde ambas casen (free + off_hours + severity >=3 + mobile + chat + prior >=10), R0005 es más específica y debe ganar."
}

{
  "action": "BILLING_SPECIALIST",
  "conditions": [
    {"attr": "product", "op": "eq", "value": "billing"},
    {"attr": "severity", "op": "gte", "value": 3}
  ],
  "beats": [],
